// Only new listings that pass the filter and have a photo, at most 15 per run (cost control).
// One photo per listing (the cover photo from the search results): ~1k tokens with Haiku.
// A one-off backfill can raise the limit by sending _photo_limit on the items.
const MAX = Math.min(Number($input.first()?.json?._photo_limit) || 15, 150);
return $input.all()
  .filter(i => i.json.prosao_filter === true && /^https:\/\//.test(i.json.slika || ''))
  .slice(0, MAX)
  .map(i => ({ json: { id: i.json.id, slika: i.json.slika } }));

// Claude returns JSON → validate. kvalitet = mean of condition and furnishing (1–5), null if the photo is not an interior.
// Haiku also spends output tokens on thinking, so a reply can be cut off mid-JSON (lesson 31): maxTokens is 1500,
// and if JSON.parse still fails, the two scores are read with a regex from the truncated text.
// Output: only id + fields; the Orchestrator merges them into the listing.
const base = $('SelectForPhoto').item.json;
const blocks = Array.isArray($json.content) ? $json.content : [];
const raw = String($json.merged_response || blocks.filter(c => c.type === 'text').map(c => c.text).join('') || $json.text || '');
let p = null;
try { p = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1)); } catch (e) { p = null; }
if (!p) {
  const num = k => { const m = raw.match(new RegExp('"' + k + '"\\s*:\\s*(null|\\d+(?:\\.\\d+)?)')); return m ? (m[1] === 'null' ? null : Number(m[1])) : undefined; };
  const st = num('stanje'), op = num('opremljenost');
  if (st !== undefined && op !== undefined) p = { stanje: st, opremljenost: op, opis: null };
}
const score = v => { const n = Number(v); return v === null || v === undefined || !Number.isFinite(n) ? null : Math.min(5, Math.max(1, n)); };
const s = p ? score(p.stanje) : null;
const o = p ? score(p.opremljenost) : null;
const parts = [s, o].filter(x => x !== null);
const kvalitet = parts.length ? Math.round(parts.reduce((a, b) => a + b, 0) / parts.length * 10) / 10 : null;
// The model sometimes mixes a Cyrillic letter into Latin text ("namešten" with Cyrillic е/н) → transliterate.
const CYR = { 'а':'a','б':'b','в':'v','г':'g','д':'d','ђ':'đ','е':'e','ж':'ž','з':'z','и':'i','ј':'j','к':'k','л':'l','љ':'lj','м':'m','н':'n','њ':'nj','о':'o','п':'p','р':'r','с':'s','т':'t','ћ':'ć','у':'u','ф':'f','х':'h','ц':'c','ч':'č','џ':'dž','ш':'š' };
const lat = t => t.replace(/[Ѐ-ӿ]/g, ch => { const low = ch.toLowerCase(); const r = CYR[low] ?? ''; return ch === low ? r : r.charAt(0).toUpperCase() + r.slice(1); });
const opis = p && typeof p.opis === 'string' && p.opis.trim() ? lat(p.opis.trim()).slice(0, 80) : null;
return { json: { id: base.id, photo_ok: p !== null, kvalitet, kvalitet_opis: kvalitet === null ? null : opis, photo_greska: p ? null : String($json.error?.message ?? $json.error ?? raw.slice(0, 120)).slice(0, 200) } };

// Manual test only: one listing per source
return [
  { json: { id: '4zida_6afc81ee000a610bfe040921', prosao_filter: true, slika: 'https://resizer2.4zida.rs/4Ixz8xCrGUEg6Q8qlhLDovqeLfM7R4WY0Yyfr83Ay4Q/rs:fill:840:0:0/bG9jYWw6Ly8vNmFmYzgxZWUwMDBhNjEwYmZlMDQwOTIxLzhiYjAxYTk3MWI.jpeg' } },
